file.content:
:root {
  --bg-primary: #07090e;
  --bg-secondary: #0d121d;
  --bg-panel: rgba(13, 18, 29, 0.88);
  --border-subtle: rgba(0, 242, 254, 0.15);
  --border-active: rgba(0, 242, 254, 0.45);
  --accent-cyan: #00f2fe;
  --accent-blue: #4facfe;
  --accent-emerald: #00f5a0;
  --accent-amber: #f6d365;
  --accent-rose: #ff416c;
  --accent-purple: #b388ff;
  --text-main: #f0f4f8;
  --text-muted: #8a99ad;
  --font-mono: 'JetBrains Mono', monospace;
  --font-display: 'Rajdhani', sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-primary);
  color: var(--text-main);
  font-family: var(--font-mono);
  overflow-x: hidden;
  user-select: none;
}

/* Glassmorphism Tactical Panel */
.tactical-panel {
  background: var(--bg-panel);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  backdrop-filter: blur(12px);
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.45);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.tactical-panel:hover {
  border-color: var(--border-active);
}

.tactical-title {
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

/* Custom Tactical Scrollbars */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.2);
}
::-webkit-scrollbar-thumb {
  background: var(--border-subtle);
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--accent-cyan);
}

/* Glowing Neon Elements */
.glow-cyan {
  text-shadow: 0 0 10px rgba(0, 242, 254, 0.6);
}
.glow-emerald {
  text-shadow: 0 0 10px rgba(0, 245, 160, 0.6);
}
.glow-amber {
  text-shadow: 0 0 10px rgba(246, 211, 101, 0.6);
}
.glow-rose {
  text-shadow: 0 0 10px rgba(255, 65, 108, 0.6);
}

/* Tactical Buttons adhering to UI/UX Doctrine */
.tactical-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 38px;
  padding: 0 14px;
  border: 1px solid var(--border-subtle);
  border-radius: 6px;
  background: rgba(13, 18, 29, 0.7);
  color: var(--text-main);
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.05em;
  cursor: pointer;
  transition: all 0.15s ease;
}

.tactical-btn:hover {
  background: rgba(0, 242, 254, 0.12);
  border-color: var(--accent-cyan);
  color: #fff;
}

.tactical-btn-primary {
  background: rgba(0, 242, 254, 0.2);
  border-color: var(--accent-cyan);
  color: var(--accent-cyan);
}

.tactical-btn-primary:hover {
  background: var(--accent-cyan);
  color: #07090e;
}

.tactical-btn-danger {
  background: rgba(255, 65, 108, 0.18);
  border-color: var(--accent-rose);
  color: var(--accent-rose);
}

.tactical-btn-danger:hover {
  background: var(--accent-rose);
  color: #fff;
}

.tactical-btn-success {
  background: rgba(0, 245, 160, 0.18);
  border-color: var(--accent-emerald);
  color: var(--accent-emerald);
}

.tactical-btn-success:hover {
  background: var(--accent-emerald);
  color: #07090e;
}

/* Tactical Range Sliders */
input[type="range"] {
  appearance: none;
  background: rgba(255, 255, 255, 0.08);
  height: 6px;
  border-radius: 3px;
  outline: none;
}
input[type="range"]::-webkit-slider-thumb {
  appearance: none;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--accent-cyan);
  cursor: pointer;
  box-shadow: 0 0 8px var(--accent-cyan);
  transition: transform 0.1s ease;
}
input[type="range"]::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

/* Scanline HUD effect */
.scanlines {
  background: linear-gradient(
    rgba(18, 16, 16, 0) 50%,
    rgba(0, 0, 0, 0.25) 50%
  );
  background-size: 100% 4px;
  pointer-events: none;
}

import { JointConfig } from './arm';

export interface ArmDimensions {
  baseHeightMm: number;    // d1
  upperArmLengthMm: number;// a2
  forearmLengthMm: number; // a3
  wristPitchMm: number;    // d4
  wristRollMm: number;     // d5
  gripperOffsetMm: number; // d6 (TCP)
}

export const DEFAULT_ARM_DIMENSIONS: ArmDimensions = {
  baseHeightMm: 180,
  upperArmLengthMm: 280,
  forearmLengthMm: 260,
  wristPitchMm: 140,
  wristRollMm: 80,
  gripperOffsetMm: 90,
};

export const DEFAULT_JOINT_CONFIGS: JointConfig[] = [
  { id: 1, name: 'J1 Base Yaw', minDeg: -170, maxDeg: 170, maxVelDegPerSec: 150, maxTorqueNm: 85, linkLengthMm: 180 },
  { id: 2, name: 'J2 Shoulder', minDeg: -70, maxDeg: 110, maxVelDegPerSec: 120, maxTorqueNm: 120, linkLengthMm: 280 },
  { id: 3, name: 'J3 Elbow', minDeg: -130, maxDeg: 130, maxVelDegPerSec: 150, maxTorqueNm: 75, linkLengthMm: 260 },
  { id: 4, name: 'J4 Wrist Pitch', minDeg: -110, maxDeg: 110, maxVelDegPerSec: 200, maxTorqueNm: 35, linkLengthMm: 140 },
  { id: 5, name: 'J5 Wrist Roll', minDeg: -180, maxDeg: 180, maxVelDegPerSec: 240, maxTorqueNm: 20, linkLengthMm: 80 },
  { id: 6, name: 'J6 Gripper', minDeg: 0, maxDeg: 60, maxVelDegPerSec: 120, maxTorqueNm: 15, linkLengthMm: 90 },
];

