file.content:
export interface Vector3D {
  x: number;
  y: number;
  z: number;
}

export interface Euler3D {
  pitch: number; // degrees
  roll: number;  // degrees
  yaw: number;   // degrees
}

export interface Pose3D {
  position: Vector3D;  // in millimeters
  orientation: Euler3D; // in degrees
}

export interface JointConfig {
  id: number;
  name: string;
  minDeg: number;
  maxDeg: number;
  maxVelDegPerSec: number;
  maxTorqueNm: number;
  linkLengthMm: number;
}

export interface JointState {
  id: number;
  name: string;
  angleDeg: number;
  targetAngleDeg: number;
  velocityDegPerSec: number;
  torqueNm: number;
  tempC: number;
  currentA: number;
  errorDeg: number;
}

export interface ForceTorqueWrench {
  fx: number; // N
  fy: number; // N
  fz: number; // N
  tx: number; // Nm
  ty: number; // Nm
  tz: number; // Nm
}

export interface EndEffectorState {
  pose: Pose3D;
  targetPose: Pose3D;
  gripperWidthMm: number; // 0 (closed) to 60 (fully open)
  isGripping: boolean;
  gripForceN: number;
  grippedObjectId: string | null;
  wrench: ForceTorqueWrench;
  tableDistanceMm: number;
}

export interface Workpiece {
  id: string;
  name: string;
  position: Vector3D;
  size: Vector3D;
  massKg: number;
  color: string;
  isGripAttached: boolean;
}

