import React from 'react';
import { TelemetryFrame } from '../types/telemetry';

interface TelemetryStripProps {
  telemetry: TelemetryFrame;
}

export const TelemetryStrip: React.FC<TelemetryStripProps> = ({ telemetry }) => {
  const { tcpPose, joints, power, manipulability, endEffector } = telemetry;
  const { position, orientation } = tcpPose;

  return (
    <div
      className="tactical-panel"
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        height: '42px',
        padding: '0 16px',
        margin: '0 8px 6px 8px',
        fontSize: '11px',
        color: 'var(--text-muted)',
      }}
    >
      {/* 1. Tool Center Point (TCP) Coordinates */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
        <span style={{ color: 'var(--accent-cyan)', fontWeight: 700 }}>TCP POSE</span>
        <span>
          X: <b style={{ color: '#fff' }}>{position.x.toFixed(1)}</b> mm
        </span>
        <span>
          Y: <b style={{ color: '#fff' }}>{position.y.toFixed(1)}</b> mm
        </span>
        <span>
          Z: <b style={{ color: '#fff' }}>{position.z.toFixed(1)}</b> mm
        </span>
        <span style={{ borderLeft: '1px solid var(--border-subtle)', height: '18px' }} />
        <span>
          P: <b style={{ color: '#fff' }}>{orientation.pitch.toFixed(1)}°</b>
        </span>
        <span>
          R: <b style={{ color: '#fff' }}>{orientation.roll.toFixed(1)}°</b>
        </span>
        <span>
          Y: <b style={{ color: '#fff' }}>{orientation.yaw.toFixed(1)}°</b>
        </span>
      </div>

      {/* 2. Joint Angles J1 - J6 */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
        <span style={{ color: 'var(--accent-emerald)', fontWeight: 700 }}>JOINTS</span>
        {joints.map((j) => (
          <span key={j.id} title={`${j.name}: ${j.angleDeg}°`}>
            J{j.id}: <b style={{ color: '#fff' }}>{j.angleDeg.toFixed(0)}°</b>
          </span>
        ))}
      </div>

      {/* 3. Manipulability, Gripper & Power */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
        <span>
          DEXTERITY:{' '}
          <b
            style={{
              color: manipulability < 0.2 ? 'var(--accent-rose)' : 'var(--accent-cyan)',
            }}
          >
            {(manipulability * 100).toFixed(0)}%
          </b>
        </span>
        <span>
          GRIPPER:{' '}
          <b style={{ color: endEffector.isGripping ? 'var(--accent-emerald)' : '#fff' }}>
            {endEffector.gripperWidthMm.toFixed(0)}mm
          </b>
        </span>
        <span>
          PWR: <b style={{ color: '#fff' }}>{power.totalWatts.toFixed(0)}W</b>
        </span>
      </div>
    </div>
  );
};

