import React from 'react';
import {
  AlertOctagon,
  CheckCircle2,
  Cpu,
  Power,
  RotateCcw,
  Volume2,
  VolumeX,
  Zap,
} from 'lucide-react';
import { ControlMode, ServoState, TelemetryFrame } from '../types/telemetry';

interface HeaderProps {
  telemetry: TelemetryFrame;
  servoState: ServoState;
  controlMode: ControlMode;
  isAudioMuted: boolean;
  onToggleServoPower: () => void;
  onToggleEStop: () => void;
  onSelectControlMode: (mode: ControlMode) => void;
  onToggleAudio: () => void;
  onResetToHome: () => void;
}

export const Header: React.FC<HeaderProps> = ({
  telemetry,
  servoState,
  controlMode,
  isAudioMuted,
  onToggleServoPower,
  onToggleEStop,
  onSelectControlMode,
  onToggleAudio,
  onResetToHome,
}) => {
  const isEstop = servoState === 'ESTOP';
  const isEngaged = servoState === 'ENGAGED';

  const modes: { label: string; mode: ControlMode }[] = [
    { label: 'JOINT JOG', mode: 'JOG' },
    { label: 'CARTESIAN IK', mode: 'CARTESIAN' },
    { label: 'TRAJECTORY', mode: 'TRAJECTORY' },
    { label: 'FAT SUITE', mode: 'FAT_CYCLE' },
    { label: 'HOME', mode: 'HOME' },
  ];

  return (
    <header
      className="tactical-panel"
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        height: '62px',
        padding: '0 16px',
        margin: '6px 8px 4px 8px',
        borderLeft: isEstop
          ? '4px solid var(--accent-rose)'
          : isEngaged
          ? '4px solid var(--accent-emerald)'
          : '4px solid var(--accent-amber)',
      }}
    >
      {/* Title & System Status */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '14px' }}>
        <div
          style={{
            width: '36px',
            height: '36px',
            borderRadius: '6px',
            background: isEstop ? 'rgba(255, 65, 108, 0.2)' : 'rgba(0, 242, 254, 0.15)',
            border: isEstop ? '1px solid var(--accent-rose)' : '1px solid var(--accent-cyan)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          <Cpu size={20} color={isEstop ? 'var(--accent-rose)' : 'var(--accent-cyan)'} />
        </div>
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <span className="tactical-title" style={{ fontSize: '15px', color: '#fff' }}>
              FAUST-KINEMATICS // 6-DOF RIG
            </span>
            <span
              style={{
                fontSize: '10px',
                padding: '2px 6px',
                borderRadius: '4px',
                background: isEstop ? 'var(--accent-rose)' : isEngaged ? 'rgba(0,245,160,0.2)' : 'rgba(246,211,101,0.2)',
                color: isEstop ? '#fff' : isEngaged ? 'var(--accent-emerald)' : 'var(--accent-amber)',
                fontWeight: 700,
              }}
            >
              {servoState}
            </span>
          </div>
          <div style={{ fontSize: '11px', color: 'var(--text-muted)' }}>
            CYCLE COUNT: {telemetry.cycleCount} | BUS: {telemetry.power.busVoltage}V | {telemetry.power.totalWatts}W
          </div>
        </div>
      </div>

      {/* Mode Selectors */}
      <div style={{ display: 'flex', gap: '4px', background: 'rgba(0,0,0,0.3)', padding: '3px', borderRadius: '6px' }}>
        {modes.map((m) => {
          const active = controlMode === m.mode;
          return (
            <button
              key={m.mode}
              onClick={() => onSelectControlMode(m.mode)}
              className="tactical-btn"
              style={{
                minHeight: '32px',
                padding: '0 12px',
                fontSize: '12px',
                background: active ? 'rgba(0, 242, 254, 0.25)' : 'transparent',
                borderColor: active ? 'var(--accent-cyan)' : 'transparent',
                color: active ? '#fff' : 'var(--text-muted)',
              }}
            >
              {m.label}
            </button>
          );
        })}
      </div>

      {/* Primary Actions & E-Stop */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
        {/* Audio Mute Toggle */}
        <button
          onClick={onToggleAudio}
          className="tactical-btn"
          title={isAudioMuted ? 'Unmute Audio' : 'Mute Audio'}
          style={{ width: '36px', height: '36px', padding: 0 }}
        >
          {isAudioMuted ? <VolumeX size={16} /> : <Volume2 size={16} color="var(--accent-cyan)" />}
        </button>

        {/* Home / Zero Calibration */}
        <button
          onClick={onResetToHome}
          className="tactical-btn"
          title="Return Arm to Calibrated Home Pose"
          style={{ height: '36px' }}
        >
          <RotateCcw size={14} /> HOME
        </button>

        {/* Servo Power Toggle */}
        <button
          onClick={onToggleServoPower}
          className={`tactical-btn ${isEngaged ? 'tactical-btn-success' : ''}`}
          style={{ height: '36px' }}
        >
          <Power size={14} /> {isEngaged ? 'SERVO ON' : 'SERVO OFF'}
        </button>

        {/* Master E-Stop */}
        <button
          onClick={onToggleEStop}
          className="tactical-btn tactical-btn-danger"
          style={{
            height: '36px',
            fontWeight: 800,
            background: isEstop ? 'var(--accent-rose)' : 'rgba(255, 65, 108, 0.25)',
            color: isEstop ? '#fff' : 'var(--accent-rose)',
          }}
        >
          <AlertOctagon size={16} /> {isEstop ? 'RESET E-STOP' : 'E-STOP'}
        </button>
      </div>
    </header>
  );
};

