1	import { ArmDimensions, DEFAULT_ARM_DIMENSIONS, DEFAULT_JOINT_CONFIGS } from '../types/kinematics';
2	import { Euler3D, Pose3D, Vector3D } from '../types/arm';
3	
4	export interface JointPositions3D {
5	  base: Vector3D;
6	  shoulder: Vector3D;
7	  elbow: Vector3D;
8	  wristPitch: Vector3D;
9	  wristRoll: Vector3D;
10	  tcp: Vector3D;
11	}
12	
13	export class KinematicsEngine {
14	  private dims: ArmDimensions;
15	
16	  constructor(dims: ArmDimensions = DEFAULT_ARM_DIMENSIONS) {
17	    this.dims = dims;
18	  }
19	
20	  /**
21	   * Forward Kinematics: Calculates all intermediate joint 3D positions and final TCP pose.
22	   * Coordinate system: Y = Up, X = Right/Forward, Z = Depth/Lateral
23	   */
24	  public forwardKinematics(anglesDeg: number[]): { positions: JointPositions3D; tcpPose: Pose3D } {
25	    const j1 = (anglesDeg[0] * Math.PI) / 180; // Base yaw
26	    const j2 = (anglesDeg[1] * Math.PI) / 180; // Shoulder pitch
27	    const j3 = (anglesDeg[2] * Math.PI) / 180; // Elbow pitch
28	    const j4 = (anglesDeg[3] * Math.PI) / 180; // Wrist pitch
29	    const j5 = (anglesDeg[4] * Math.PI) / 180; // Wrist roll
30	
31	    // Base
32	    const base: Vector3D = { x: 0, y: 0, z: 0 };
33	    // Shoulder (height d1)
34	    const shoulder: Vector3D = { x: 0, y: this.dims.baseHeightMm, z: 0 };
35	
36	    // Cumulative pitch angles
37	    const theta2 = j2;
38	    const theta23 = j2 + j3;
39	    const theta234 = j2 + j3 + j4;
40	
41	    // Planar reach in arm plane (r = radial distance from base axis, y = height)
42	    const rElbow = this.dims.upperArmLengthMm * Math.sin(theta2);
43	    const yElbow = shoulder.y + this.dims.upperArmLengthMm * Math.cos(theta2);
44	
45	    const rWristPitch = rElbow + this.dims.forearmLengthMm * Math.sin(theta23);
46	    const yWristPitch = yElbow + this.dims.forearmLengthMm * Math.cos(theta23);
47	
48	    const rWristRoll = rWristPitch + this.dims.wristPitchMm * Math.sin(theta234);
49	    const yWristRoll = yWristPitch + this.dims.wristPitchMm * Math.cos(theta234);
50	
51	    const totalToolDist = this.dims.wristRollMm + this.dims.gripperOffsetMm;
52	    const rTcp = rWristRoll + totalToolDist * Math.sin(theta234);
53	    const yTcp = yWristRoll + totalToolDist * Math.cos(theta234);
54	
55	    // Project planar (r, y) into 3D world with base rotation j1
56	    // J1 = 0 => pointing along +X axis
57	    const toWorld = (r: number, y: number): Vector3D => ({
58	      x: r * Math.cos(j1),
59	      y: y,
60	      z: -r * Math.sin(j1),
61	    });
62	
63	    const elbow = toWorld(rElbow, yElbow);
64	    const wristPitch = toWorld(rWristPitch, yWristPitch);
65	    const wristRoll = toWorld(rWristRoll, yWristRoll);
66	    const tcp = toWorld(rTcp, yTcp);
67	
68	    const orientation: Euler3D = {
69	      pitch: Number(((theta234 * 180) / Math.PI).toFixed(1)),
70	      roll: Number((anglesDeg[4]).toFixed(1)),
71	      yaw: Number((anglesDeg[0]).toFixed(1)),
72	    };
73	
74	    return {
75	      positions: { base, shoulder, elbow, wristPitch, wristRoll, tcp },
76	      tcpPose: { position: tcp, orientation },
77	    };
78	  }
79	
80	  /**
81	   * Fast Numerical Inverse Kinematics (Jacobian Transpose with Joint Limits & Damping)
82	   */
83	  public inverseKinematics(
84	    targetPos: Vector3D,
85	    currentAngles: number[],
86	    targetPitchDeg = 0
87	  ): { anglesDeg: number[]; converged: boolean; errorMm: number } {
88	    const angles = [...currentAngles];
89	    const maxIterations = 35;
90	    const toleranceMm = 1.0;
91	    const alpha = 0.0004; // Step rate
92	
93	    for (let iter = 0; iter < maxIterations; iter++) {
94	      const { tcpPose } = this.forwardKinematics(angles);
95	      const dx = targetPos.x - tcpPose.position.x;
96	      const dy = targetPos.y - tcpPose.position.y;
97	      const dz = targetPos.z - tcpPose.position.z;
98	      const errDist = Math.sqrt(dx * dx + dy * dy + dz * dz);
99	
100	      if (errDist < toleranceMm) {
101	        return { anglesDeg: angles, converged: true, errorMm: errDist };
102	      }
103	
104	      // Analytical base yaw
105	      const targetBaseYaw = (Math.atan2(-targetPos.z, targetPos.x) * 180) / Math.PI;
106	      angles[0] += (targetBaseYaw - angles[0]) * 0.25;
107	
108	      // Numeric gradient for arm joints (J2, J3, J4)
109	      const delta = 0.1;
110	      for (let j = 1; j <= 3; j++) {
111	        angles[j] += delta;
112	        const fkPlus = this.forwardKinematics(angles).tcpPose.position;
113	        angles[j] -= delta;
114	
115	        const jx = (fkPlus.x - tcpPose.position.x) / delta;
116	        const jy = (fkPlus.y - tcpPose.position.y) / delta;
117	        const jz = (fkPlus.z - tcpPose.position.z) / delta;
118	
119	        const dAngle = alpha * (jx * dx + jy * dy + jz * dz);
120	        angles[j] += dAngle;
121	
122	        // Clamp to joint limits
123	        const cfg = DEFAULT_JOINT_CONFIGS[j];
124	        angles[j] = Math.max(cfg.minDeg, Math.min(cfg.maxDeg, angles[j]));
125	      }
126	
127	      // Wrist pitch orient towards target pitch
128	      angles[3] += (targetPitchDeg - (angles[1] + angles[2] + angles[3])) * 0.1;
129	      const cfg3 = DEFAULT_JOINT_CONFIGS[3];
130	      angles[3] = Math.max(cfg3.minDeg, Math.min(cfg3.maxDeg, angles[3]));
131	    }
132	
133	    const finalFk = this.forwardKinematics(angles).tcpPose.position;
134	    const finalErr = Math.sqrt(
135	      Math.pow(targetPos.x - finalFk.x, 2) +
136	      Math.pow(targetPos.y - finalFk.y, 2) +
137	      Math.pow(targetPos.z - finalFk.z, 2)
138	    );
139	
140	    return { anglesDeg: angles, converged: finalErr < 5.0, errorMm: finalErr };
141	  }
142	
143	  /**
144	   * Calculates Yoshikawa Manipulability Measure (distance from singularity)
145	   */
146	  public computeManipulability(anglesDeg: number[]): number {
147	    const q2 = (anglesDeg[1] * Math.PI) / 180;
148	    const q3 = (anglesDeg[2] * Math.PI) / 180;
149	    // Elbow extension singularity occurs when sin(q3) approaches 0
150	    const elbowSingularity = Math.abs(Math.sin(q3));
151	    // Shoulder overhead singularity occurs when arm is vertical
152	    const shoulderFactor = Math.abs(Math.cos(q2)) * 0.5 + 0.5;
153	    return Math.max(0.01, Math.min(1.0, elbowSingularity * shoulderFactor));
154	  }
155	}
