1	import { DEFAULT_JOINT_CONFIGS } from '../types/kinematics';
2	import { ForceTorqueWrench, JointState, Vector3D } from '../types/arm';
3	import { PowerTelemetry } from '../types/telemetry';
4	
5	export class DynamicsEngine {
6	  private motorTemps: number[] = [28, 29, 28, 27, 26, 25];
7	  private jointVelocities: number[] = [0, 0, 0, 0, 0, 0];
8	  private actualAngles: number[] = [0, 30, 45, -75, 0, 30]; // Calibrated home pose
9	
10	  public update(
11	    dt: number,
12	    targetAnglesDeg: number[],
13	    payloadKg: number,
14	    isEStop: boolean
15	  ): {
16	    joints: JointState[];
17	    power: PowerTelemetry;
18	    wrench: ForceTorqueWrench;
19	  } {
20	    const states: JointState[] = [];
21	    let totalWatts = 24.5; // Idle base electronics quiescent power
22	
23	    // Link masses (kg)
24	    const linkMasses = [4.5, 3.8, 2.6, 1.2, 0.8, 0.5];
25	
26	    for (let i = 0; i < 6; i++) {
27	      const cfg = DEFAULT_JOINT_CONFIGS[i];
28	      let target = targetAnglesDeg[i];
29	
30	      if (isEStop) {
31	        target = this.actualAngles[i]; // Freeze commanded target immediately
32	      }
33	
34	      // PID position loop response
35	      const err = target - this.actualAngles[i];
36	      const maxStep = cfg.maxVelDegPerSec * dt;
37	      const step = Math.max(-maxStep, Math.min(maxStep, err * 6.0 * dt));
38	
39	      this.actualAngles[i] += step;
40	      this.jointVelocities[i] = step / dt;
41	
42	      // Gravity torque estimation (primarily on J2 and J3)
43	      let gravityTorque = 0;
44	      if (i === 1) { // Shoulder
45	        const rad = (this.actualAngles[1] * Math.PI) / 180;
46	        gravityTorque = (linkMasses[1] * 0.15 + (linkMasses[2] + payloadKg) * 0.35) * 9.81 * Math.sin(rad);
47	      } else if (i === 2) { // Elbow
48	        const rad = ((this.actualAngles[1] + this.actualAngles[2]) * Math.PI) / 180;
49	        gravityTorque = (linkMasses[2] * 0.13 + payloadKg * 0.28) * 9.81 * Math.sin(rad);
50	      }
51	
52	      // Dynamic acceleration torque
53	      const accelTorque = Math.abs(step / dt) * 0.05;
54	      const torque = Math.min(cfg.maxTorqueNm, Math.abs(gravityTorque) + accelTorque + 1.2);
55	
56	      // Motor current (torque constant Kt approx 0.85 Nm/A)
57	      const current = Number((torque / 0.85 + 0.3).toFixed(2));
58	      const motorWatts = torque * Math.abs((this.jointVelocities[i] * Math.PI) / 180) + Math.pow(current, 2) * 0.45;
59	      totalWatts += motorWatts;
60	
61	      // Thermal model: Joule heating vs ambient dissipation
62	      const heatGen = (current * current * 0.008) * dt;
63	      const cooling = (this.motorTemps[i] - 25.0) * 0.012 * dt;
64	      this.motorTemps[i] = Math.max(25.0, Math.min(85.0, this.motorTemps[i] + heatGen - cooling));
65	
66	      states.push({
67	        id: cfg.id,
68	        name: cfg.name,
69	        angleDeg: Number(this.actualAngles[i].toFixed(2)),
70	        targetAngleDeg: Number(target.toFixed(2)),
71	        velocityDegPerSec: Number(this.jointVelocities[i].toFixed(1)),
72	        torqueNm: Number(torque.toFixed(2)),
73	        tempC: Number(this.motorTemps[i].toFixed(1)),
74	        currentA: current,
75	        errorDeg: Number(err.toFixed(3)),
76	      });
77	    }
78	
79	    const busVoltage = 48.0 - (totalWatts / 48.0) * 0.08;
80	    const totalCurrent = Number((totalWatts / busVoltage).toFixed(2));
81	
82	    // End-effector F/T sensor reading
83	    const wrench: ForceTorqueWrench = {
84	      fx: Number((payloadKg * 0.15).toFixed(2)),
85	      fy: Number((-payloadKg * 9.81 - 1.5).toFixed(2)),
86	      fz: Number((payloadKg * 0.08).toFixed(2)),
87	      tx: 0.12,
88	      ty: 0.05,
89	      tz: 0.08,
90	    };
91	
92	    return {
93	      joints: states,
94	      power: {
95	        busVoltage: Number(busVoltage.toFixed(1)),
96	        totalCurrent,
97	        totalWatts: Number(totalWatts.toFixed(1)),
98	        peakWatts: 340,
99	      },
100	      wrench,
101	    };
102	  }
103	
104	  public getActualAngles(): number[] {
105	    return [...this.actualAngles];
106	  }
107	
108	  public setActualAngles(angles: number[]): void {
109	    this.actualAngles = [...angles];
110	  }
111	
112	  public resetToHome(): void {
113	    this.actualAngles = [0, 30, 45, -75, 0, 30];
114	    this.jointVelocities = [0, 0, 0, 0, 0, 0];
115	  }
116	}
