1	class RoboticSoundEngine {
2	  private ctx: AudioContext | null = null;
3	  private isMuted = true;
4	  private servoOsc: OscillatorNode | null = null;
5	  private servoGain: GainNode | null = null;
6	  private isInitialized = false;
7	
8	  private initAudio(): void {
9	    if (this.isInitialized) return;
10	    try {
11	      const AudioCtx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
12	      this.ctx = new AudioCtx();
13	
14	      // Servo motor synthesis oscillator
15	      this.servoOsc = this.ctx.createOscillator();
16	      this.servoOsc.type = 'sawtooth';
17	      this.servoOsc.frequency.setValueAtTime(140, this.ctx.currentTime);
18	
19	      this.servoGain = this.ctx.createGain();
20	      this.servoGain.gain.setValueAtTime(0.0, this.ctx.currentTime);
21	
22	      // Lowpass filter to give realistic muffled industrial servo tone
23	      const filter = this.ctx.createBiquadFilter();
24	      filter.type = 'lowpass';
25	      filter.frequency.setValueAtTime(1200, this.ctx.currentTime);
26	
27	      this.servoOsc.connect(filter);
28	      filter.connect(this.servoGain);
29	      this.servoGain.connect(this.ctx.destination);
30	      this.servoOsc.start();
31	
32	      this.isInitialized = true;
33	    } catch {
34	      // AudioContext unavailable or restricted
35	    }
36	  }
37	
38	  public setMute(muted: boolean): void {
39	    this.isMuted = muted;
40	    if (!muted && !this.isInitialized) {
41	      this.initAudio();
42	    }
43	    if (this.servoGain && this.ctx) {
44	      this.servoGain.gain.setValueAtTime(muted ? 0.0 : 0.05, this.ctx.currentTime);
45	    }
46	  }
47	
48	  public updateMotorSound(totalJointVelocity: number): void {
49	    if (this.isMuted || !this.ctx || !this.servoOsc || !this.servoGain) return;
50	    const baseFreq = 140;
51	    const freq = Math.min(800, baseFreq + totalJointVelocity * 2.8);
52	    this.servoOsc.frequency.setTargetAtTime(freq, this.ctx.currentTime, 0.05);
53	
54	    const gain = Math.min(0.08, (totalJointVelocity / 300) * 0.08);
55	    this.servoGain.gain.setTargetAtTime(gain, this.ctx.currentTime, 0.05);
56	  }
57	
58	  public playGripperSolenoid(): void {
59	    if (this.isMuted || !this.ctx) return;
60	    try {
61	      // Pneumatic burst noise
62	      const bufferSize = this.ctx.sampleRate * 0.08;
63	      const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
64	      const output = buffer.getChannelData(0);
65	      for (let i = 0; i < bufferSize; i++) {
66	        output[i] = Math.random() * 2 - 1;
67	      }
68	      const whiteNoise = this.ctx.createBufferSource();
69	      whiteNoise.buffer = buffer;
70	
71	      const filter = this.ctx.createBiquadFilter();
72	      filter.type = 'bandpass';
73	      filter.frequency.setValueAtTime(1800, this.ctx.currentTime);
74	
75	      const gain = this.ctx.createGain();
76	      gain.gain.setValueAtTime(0.09, this.ctx.currentTime);
77	      gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.08);
78	
79	      whiteNoise.connect(filter);
80	      filter.connect(gain);
81	      gain.connect(this.ctx.destination);
82	      whiteNoise.start();
83	    } catch {
