import { TelemetryFrame } from '../types/telemetry';

class BlackboxRecorder {
  private frames: TelemetryFrame[] = [];
  private maxFrames = 3600; // 60 seconds buffer

  public addFrame(frame: TelemetryFrame): void {
    if (this.frames.length >= this.maxFrames) {
      this.frames.shift();
    }
    this.frames.push(frame);
  }

  public getFrameCount(): number {
    return this.frames.length;
  }

  public getFrameAt(index: number): TelemetryFrame | null {
    if (index >= 0 && index < this.frames.length) {
      return this.frames[index];
    }
    return null;
  }

  public clear(): void {
    this.frames = [];
  }

  public exportJson(): void {
    const dataStr = 'data:text/json;charset=utf-8,' + encodeURIComponent(JSON.stringify(this.frames, null, 2));
    const downloadAnchor = document.createElement('a');
    downloadAnchor.setAttribute('href', dataStr);
    downloadAnchor.setAttribute('download', `blackbox_robotic_arm_${Date.now()}.json`);
    document.body.appendChild(downloadAnchor);
    downloadAnchor.click();
    downloadAnchor.remove();
  }
}

export const blackboxRecorder = new BlackboxRecorder();

