import * as THREE from 'three';
import { JointPositions3D } from '../../engine/kinematicsEngine';
import { Workpiece } from '../../types/arm';

export interface ArmMeshes {
  rootGroup: THREE.Group;
  jointSpheres: THREE.Mesh[];
  linkMeshes: THREE.Mesh[];
  leftFinger: THREE.Mesh;
  rightFinger: THREE.Mesh;
  tcpHelper: THREE.AxesHelper;
  tcpLaser: THREE.Line;
  workpieceMeshes: Map<string, THREE.Mesh>;
}

const SCALE = 0.001; // mm to meters

function createMaterial(color: number, roughness = 0.35, metalness = 0.85): THREE.MeshStandardMaterial {
  return new THREE.MeshStandardMaterial({
    color,
    roughness,
    metalness,
  });
}

function orientCylinder(mesh: THREE.Mesh, from: THREE.Vector3, to: THREE.Vector3): void {
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length();
  mesh.scale.set(1, len, 1);
  mesh.position.copy(from).addScaledVector(dir, 0.5);

  if (len > 0.0001) {
    const up = new THREE.Vector3(0, 1, 0);
    const quat = new THREE.Quaternion().setFromUnitVectors(up, dir.normalize());
    mesh.quaternion.copy(quat);
  }
}

export function buildArmScene(): ArmMeshes {
  const rootGroup = new THREE.Group();

  // Materials
  const baseMat = createMaterial(0x1a2233, 0.4, 0.9);
  const darkMetalMat = createMaterial(0x111622, 0.3, 0.95);
  const linkMat = createMaterial(0x242e42, 0.3, 0.85);
  const jointMat = createMaterial(0x00f2fe, 0.2, 0.7);
  const gripperMat = createMaterial(0x323e54, 0.3, 0.85);

  // 1. Pedestal Base
  const baseGeo = new THREE.CylinderGeometry(0.14, 0.16, 0.06, 32);
  const baseMesh = new THREE.Mesh(baseGeo, baseMat);
  baseMesh.position.y = 0.03;
  baseMesh.castShadow = true;
  baseMesh.receiveShadow = true;
  rootGroup.add(baseMesh);

  // Pedestal accent ring
  const ringGeo = new THREE.TorusGeometry(0.142, 0.006, 16, 48);
  const ringMat = new THREE.MeshBasicMaterial({ color: 0x00f2fe });
  const ringMesh = new THREE.Mesh(ringGeo, ringMat);
  ringMesh.rotation.x = Math.PI / 2;
  ringMesh.position.y = 0.055;
  rootGroup.add(ringMesh);

  // 2. Links (Cylinders scaled along Y)
  const linkGeo = new THREE.CylinderGeometry(0.045, 0.045, 1, 24);
  const upperGeo = new THREE.CylinderGeometry(0.042, 0.042, 1, 24);
  const foreGeo = new THREE.CylinderGeometry(0.035, 0.035, 1, 24);
  const wristGeo = new THREE.CylinderGeometry(0.026, 0.026, 1, 24);

  const basePillar = new THREE.Mesh(linkGeo, darkMetalMat);
  const upperArm = new THREE.Mesh(upperGeo, linkMat);
  const foreArm = new THREE.Mesh(foreGeo, linkMat);
  const wristPitch = new THREE.Mesh(wristGeo, darkMetalMat);
  const wristRoll = new THREE.Mesh(wristGeo, gripperMat);

  const linkMeshes = [basePillar, upperArm, foreArm, wristPitch, wristRoll];
  linkMeshes.forEach((m) => {
    m.castShadow = true;
    rootGroup.add(m);
  });

  // 3. Joint Spheres
  const jointGeo = new THREE.SphereGeometry(0.05, 24, 24);
  const smallJointGeo = new THREE.SphereGeometry(0.034, 20, 20);

  const jBase = new THREE.Mesh(jointGeo, jointMat);
  const jShoulder = new THREE.Mesh(jointGeo, jointMat);
  const jElbow = new THREE.Mesh(jointGeo, jointMat);
  const jWristP = new THREE.Mesh(smallJointGeo, jointMat);
  const jWristR = new THREE.Mesh(smallJointGeo, jointMat);

  const jointSpheres = [jBase, jShoulder, jElbow, jWristP, jWristR];
  jointSpheres.forEach((j) => {
    j.castShadow = true;
    rootGroup.add(j);
  });

  // 4. Gripper Body & Fingers
  const fingerGeo = new THREE.BoxGeometry(0.012, 0.04, 0.018);
  const fingerMat = createMaterial(0x00f5a0, 0.2, 0.8);
  const leftFinger = new THREE.Mesh(fingerGeo, fingerMat);
  const rightFinger = new THREE.Mesh(fingerGeo, fingerMat);
  leftFinger.castShadow = true;
  rightFinger.castShadow = true;
  rootGroup.add(leftFinger);
  rootGroup.add(rightFinger);

  // 5. TCP Laser line & Coordinate axes
  const tcpHelper = new THREE.AxesHelper(0.09);
  rootGroup.add(tcpHelper);

  const laserMat = new THREE.LineBasicMaterial({ color: 0x00f2fe, opacity: 0.5, transparent: true });
  const laserGeo = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, 0, 0),
    new THREE.Vector3(0, -1, 0),
  ]);
  const tcpLaser = new THREE.Line(laserGeo, laserMat);
  rootGroup.add(tcpLaser);

  const workpieceMeshes = new Map<string, THREE.Mesh>();

  return {
    rootGroup,
    jointSpheres,
    linkMeshes,
    leftFinger,
    rightFinger,
    tcpHelper,
    tcpLaser,
    workpieceMeshes,
  };
}

export function updateArmPose(
  meshes: ArmMeshes,
  pos: JointPositions3D,
  gripperWidthMm: number,
  workpieces: Workpiece[]
): void {
  const pBase = new THREE.Vector3(pos.base.x * SCALE, pos.base.y * SCALE, pos.base.z * SCALE);
  const pShoulder = new THREE.Vector3(pos.shoulder.x * SCALE, pos.shoulder.y * SCALE, pos.shoulder.z * SCALE);
  const pElbow = new THREE.Vector3(pos.elbow.x * SCALE, pos.elbow.y * SCALE, pos.elbow.z * SCALE);
  const pWristP = new THREE.Vector3(pos.wristPitch.x * SCALE, pos.wristPitch.y * SCALE, pos.wristPitch.z * SCALE);
  const pWristR = new THREE.Vector3(pos.wristRoll.x * SCALE, pos.wristRoll.y * SCALE, pos.wristRoll.z * SCALE);
  const pTcp = new THREE.Vector3(pos.tcp.x * SCALE, pos.tcp.y * SCALE, pos.tcp.z * SCALE);

  // Position joint hubs
  meshes.jointSpheres[0].position.copy(pBase);
  meshes.jointSpheres[1].position.copy(pShoulder);
  meshes.jointSpheres[2].position.copy(pElbow);
  meshes.jointSpheres[3].position.copy(pWristP);
  meshes.jointSpheres[4].position.copy(pWristR);

  // Orient link segments
  orientCylinder(meshes.linkMeshes[0], pBase, pShoulder);
  orientCylinder(meshes.linkMeshes[1], pShoulder, pElbow);
  orientCylinder(meshes.linkMeshes[2], pElbow, pWristP);
  orientCylinder(meshes.linkMeshes[3], pWristP, pWristR);
  orientCylinder(meshes.linkMeshes[4], pWristR, pTcp);

  // Tool Center Point axes & helper
  meshes.tcpHelper.position.copy(pTcp);

  // Laser line down to table surface (y = 0)
  const laserPos = meshes.tcpLaser.geometry.attributes.position;
  laserPos.setXYZ(0, pTcp.x, pTcp.y, pTcp.z);
  laserPos.setXYZ(1, pTcp.x, 0, pTcp.z);
  laserPos.needsUpdate = true;

  // Gripper fingers offset
  const halfGap = (gripperWidthMm * 0.5 * SCALE) + 0.008;
  meshes.leftFinger.position.set(pTcp.x - halfGap, pTcp.y, pTcp.z);
  meshes.rightFinger.position.set(pTcp.x + halfGap, pTcp.y, pTcp.z);

  // Workpieces update
  workpieces.forEach((wp) => {
    let wpMesh = meshes.workpieceMeshes.get(wp.id);
    if (!wpMesh) {
      const geo = new THREE.BoxGeometry(wp.size.x * SCALE, wp.size.y * SCALE, wp.size.z * SCALE);
      const mat = createMaterial(parseInt(wp.color.replace('#', '0x'), 16), 0.25, 0.7);
      wpMesh = new THREE.Mesh(geo, mat);
      wpMesh.castShadow = true;
      wpMesh.receiveShadow = true;
      meshes.rootGroup.add(wpMesh);
      meshes.workpieceMeshes.set(wp.id, wpMesh);
    }
    wpMesh.position.set(wp.position.x * SCALE, wp.position.y * SCALE, wp.position.z * SCALE);
  });
}

