import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { JointPositions3D } from '../engine/kinematicsEngine';
import { Pose3D, Workpiece } from '../types/arm';
import { ArmMeshes, buildArmScene, updateArmPose } from './viewport/armMeshBuilder';
import { Camera, Eye, Layers, RotateCcw, Trash2 } from 'lucide-react';

interface Viewport3DProps {
  positions: JointPositions3D;
  gripperWidthMm: number;
  workpieces: Workpiece[];
  tcpPose: Pose3D;
}

export const Viewport3D: React.FC<Viewport3DProps> = ({
  positions,
  gripperWidthMm,
  workpieces,
  tcpPose,
}) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const armMeshesRef = useRef<ArmMeshes | null>(null);
  const controlsRef = useRef<OrbitControls | null>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
  const trailLineRef = useRef<THREE.Line | null>(null);
  const trailPointsRef = useRef<THREE.Vector3[]>([]);

  const [showTrail, setShowTrail] = useState(true);
  const [showEnvelope, setShowEnvelope] = useState(true);

  // Setup Three.js scene
  useEffect(() => {
    const container = mountRef.current;
    if (!container) return;

    const width = container.clientWidth;
    const height = container.clientHeight;

    // 1. Scene & Camera
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x07090e);
    scene.fog = new THREE.FogExp2(0x07090e, 0.4);

    const camera = new THREE.PerspectiveCamera(45, width / height, 0.05, 50);
    camera.position.set(1.4, 1.1, 1.5);
    cameraRef.current = camera;

    // 2. Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    renderer.setSize(width, height);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
