  const setCameraView = (type: 'iso' | 'top' | 'front' | 'side') => {
    const cam = cameraRef.current;
    const ctrl = controlsRef.current;
    if (!cam || !ctrl) return;
    if (type === 'iso') cam.position.set(1.4, 1.1, 1.5);
    else if (type === 'top') cam.position.set(0.001, 2.2, 0);
    else if (type === 'front') cam.position.set(0, 0.45, 1.9);
    else if (type === 'side') cam.position.set(1.9, 0.45, 0);
    ctrl.target.set(0, 0.35, 0);
    ctrl.update();
  };

  const clearTrail = () => {
    trailPointsRef.current = [];
    if (trailLineRef.current) {
      trailLineRef.current.geometry.setDrawRange(0, 0);
      (trailLineRef.current.geometry.attributes.position as THREE.BufferAttribute).needsUpdate = true;
    }
  };

  return (
    <div style={{ position: 'relative', width: '100%', height: '100%', minHeight: '360px', overflow: 'hidden' }}>
      <div ref={mountRef} style={{ width: '100%', height: '100%' }} />

      {/* Floating HUD Viewport Bar */}
      <div
        style={{
          position: 'absolute',
          top: '12px',
          left: '12px',
          display: 'flex',
          gap: '6px',
          background: 'rgba(13, 18, 29, 0.75)',
          padding: '4px 8px',
          borderRadius: '6px',
          border: '1px solid var(--border-subtle)',
          backdropFilter: 'blur(8px)',
        }}
      >
        <button onClick={() => setCameraView('iso')} className="tactical-btn" style={{ minHeight: '28px', padding: '0 8px', fontSize: '11px' }} title="Isometric View">
          <Camera size={13} /> ISO
        </button>
        <button onClick={() => setCameraView('top')} className="tactical-btn" style={{ minHeight: '28px', padding: '0 8px', fontSize: '11px' }} title="Top Overhead">
          TOP
        </button>
        <button onClick={() => setCameraView('front')} className="tactical-btn" style={{ minHeight: '28px', padding: '0 8px', fontSize: '11px' }} title="Front Elevation">
          FRONT
        </button>
        <button onClick={() => setCameraView('side')} className="tactical-btn" style={{ minHeight: '28px', padding: '0 8px', fontSize: '11px' }} title="Side Profile">
          SIDE
        </button>
        <div style={{ width: '1px', background: 'var(--border-subtle)', margin: '0 2px' }} />
        <button
          onClick={() => setShowTrail(!showTrail)}
          className={`tactical-btn ${showTrail ? 'tactical-btn-primary' : ''}`}
          style={{ minHeight: '28px', padding: '0 8px', fontSize: '11px' }}
          title="Toggle TCP Motion Trail"
        >
          <Layers size={13} /> TRAIL
        </button>
        <button onClick={clearTrail} className="tactical-btn" style={{ minHeight: '28px', padding: '0 8px', fontSize: '11px' }} title="Clear Motion Trail">
          <Trash2 size={13} />
        </button>
      </div>

      {/* TCP Coordinates Overlay */}
      <div
        style={{
          position: 'absolute',
          bottom: '12px',
          left: '12px',
          background: 'rgba(13, 18, 29, 0.8)',
          padding: '6px 12px',
          borderRadius: '6px',
          border: '1px solid var(--border-subtle)',
          fontSize: '11px',
          display: 'flex',
          gap: '12px',
          color: 'var(--text-muted)',
          backdropFilter: 'blur(8px)',
        }}
      >
        <span style={{ color: 'var(--accent-cyan)', fontWeight: 700 }}>TCP:</span>
        <span>X: <b style={{ color: '#fff' }}>{tcpPose.position.x.toFixed(1)}</b></span>
        <span>Y: <b style={{ color: '#fff' }}>{tcpPose.position.y.toFixed(1)}</b></span>
        <span>Z: <b style={{ color: '#fff' }}>{tcpPose.position.z.toFixed(1)}</b></span>
      </div>
    </div>
  );
};

