import React from 'react';
import { DEFAULT_JOINT_CONFIGS } from '../../types/kinematics';
import { JointState } from '../../types/arm';
import { Sliders, RotateCw } from 'lucide-react';

interface JogControlPanelProps {
  jointStates: JointState[];
  targetAngles: number[];
  gripperWidth: number;
  onUpdateTargetAngle: (jointIndex: number, deg: number) => void;
  onUpdateGripperWidth: (widthMm: number) => void;
  onApplyPresetPose: (angles: number[]) => void;
  isEngaged: boolean;
}

export const JogControlPanel: React.FC<JogControlPanelProps> = ({
  jointStates,
  targetAngles,
  gripperWidth,
  onUpdateTargetAngle,
  onUpdateGripperWidth,
  onApplyPresetPose,
  isEngaged,
}) => {
  const presets = [
    { label: 'HOME', angles: [0, 30, 45, -75, 0, 30] },
    { label: 'READY', angles: [0, 15, 60, -75, 0, 60] },
    { label: 'STRETCH', angles: [0, 45, 90, -45, 0, 60] },
    { label: 'STOW', angles: [0, -45, 120, -75, 0, 0] },
  ];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
      {/* Quick Poses */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '6px' }}>
        <span className="tactical-title" style={{ fontSize: '11px', color: 'var(--text-muted)' }}>
          PRESET POSES:
        </span>
        <div style={{ display: 'flex', gap: '6px' }}>
          {presets.map((p) => (
            <button
              key={p.label}
              disabled={!isEngaged}
              onClick={() => onApplyPresetPose(p.angles)}
              className="tactical-btn"
              style={{ minHeight: '28px', padding: '0 8px', fontSize: '11px' }}
            >
              {p.label}
            </button>
          ))}
        </div>
      </div>

      {/* 6 Joint Jog Controls */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        {DEFAULT_JOINT_CONFIGS.map((cfg, idx) => {
          const state = jointStates[idx];
          const target = targetAngles[idx];
          const torquePct = state ? Math.min(100, (state.torqueNm / cfg.maxTorqueNm) * 100) : 0;

          return (
            <div
              key={cfg.id}
              style={{
                background: 'rgba(0, 0, 0, 0.25)',
                padding: '8px 10px',
                borderRadius: '6px',
                border: '1px solid rgba(255, 255, 255, 0.05)',
              }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '6px' }}>
                <span style={{ fontSize: '12px', fontWeight: 600, color: '#fff' }}>
                  {cfg.name}
                </span>
                <div style={{ display: 'flex', gap: '8px', fontSize: '11px' }}>
                  <span style={{ color: 'var(--accent-cyan)' }}>
                    CMD: <b>{target.toFixed(1)}°</b>
                  </span>
                  <span style={{ color: 'var(--text-muted)' }}>
                    ACT: <b>{state?.angleDeg.toFixed(1) ?? '--'}°</b>
                  </span>
                  <span style={{ color: torquePct > 80 ? 'var(--accent-rose)' : 'var(--text-muted)' }}>
                    {state?.torqueNm.toFixed(0) ?? 0}Nm
                  </span>
                </div>
              </div>

              {/* Slider & Step buttons */}
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                <button
                  disabled={!isEngaged}
                  onClick={() => onUpdateTargetAngle(idx, Math.max(cfg.minDeg, target - 5))}
                  className="tactical-btn"
                  style={{ minHeight: '26px', padding: '0 6px', fontSize: '10px' }}
                >
                  -5°
                </button>
                <button
                  disabled={!isEngaged}
                  onClick={() => onUpdateTargetAngle(idx, Math.max(cfg.minDeg, target - 1))}
                  className="tactical-btn"
                  style={{ minHeight: '26px', padding: '0 6px', fontSize: '10px' }}
                >
                  -1°
                </button>

                <input
                  type="range"
                  min={cfg.minDeg}
                  max={cfg.maxDeg}
                  step={0.5}
                  value={target}
                  disabled={!isEngaged}
                  onChange={(e) => onUpdateTargetAngle(idx, parseFloat(e.target.value))}
                  style={{ flex: 1 }}
                />

                <button
                  disabled={!isEngaged}
                  onClick={() => onUpdateTargetAngle(idx, Math.min(cfg.maxDeg, target + 1))}
                  className="tactical-btn"
                  style={{ minHeight: '26px', padding: '0 6px', fontSize: '10px' }}
                >
                  +1°
                </button>
                <button
                  disabled={!isEngaged}
                  onClick={() => onUpdateTargetAngle(idx, Math.min(cfg.maxDeg, target + 5))}
                  className="tactical-btn"
                  style={{ minHeight: '26px', padding: '0 6px', fontSize: '10px' }}
                >
                  +5°
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* End Effector Gripper Control */}
      <div
        style={{
          background: 'rgba(0, 0, 0, 0.3)',
          padding: '10px',
          borderRadius: '6px',
          border: '1px solid var(--border-subtle)',
        }}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
          <span style={{ fontSize: '12px', fontWeight: 600, color: 'var(--accent-emerald)' }}>
            PARALLEL JAW GRIPPER (J6)
          </span>
          <span style={{ fontSize: '12px', color: '#fff' }}>
            WIDTH: <b>{gripperWidth.toFixed(0)} mm</b>
          </span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <button
            disabled={!isEngaged}
            onClick={() => onUpdateGripperWidth(0)}
            className={`tactical-btn ${gripperWidth <= 15 ? 'tactical-btn-primary' : ''}`}
            style={{ minHeight: '30px', padding: '0 12px', fontSize: '11px' }}
          >
            CLOSE (0mm)
          </button>
          <input
            type="range"
            min={0}
            max={60}
            step={1}
            value={gripperWidth}
            disabled={!isEngaged}
            onChange={(e) => onUpdateGripperWidth(parseFloat(e.target.value))}
            style={{ flex: 1 }}
          />
          <button
            disabled={!isEngaged}
            onClick={() => onUpdateGripperWidth(60)}
            className={`tactical-btn ${gripperWidth >= 45 ? 'tactical-btn-primary' : ''}`}
            style={{ minHeight: '30px', padding: '0 12px', fontSize: '11px' }}
          >
            OPEN (60mm)
          </button>
        </div>
      </div>
    </div>
  );
};

