import React, { useState } from 'react';
import { Vector3D } from '../../types/arm';
import { Crosshair, Navigation, CheckCircle2, AlertTriangle } from 'lucide-react';

interface CartesianControlPanelProps {
  currentTcp: Vector3D;
  targetPos: Vector3D;
  targetPitch: number;
  manipulability: number;
  ikErrorMm: number;
  ikConverged: boolean;
  onUpdateTargetPos: (pos: Vector3D, pitch: number) => void;
  onSolveIK: () => void;
  isEngaged: boolean;
}

export const CartesianControlPanel: React.FC<CartesianControlPanelProps> = ({
  currentTcp,
  targetPos,
  targetPitch,
  manipulability,
  ikErrorMm,
  ikConverged,
  onUpdateTargetPos,
  onSolveIK,
  isEngaged,
}) => {
  const [posX, setPosX] = useState(targetPos.x);
  const [posY, setPosY] = useState(targetPos.y);
  const [posZ, setPosZ] = useState(targetPos.z);
  const [pitch, setPitch] = useState(targetPitch);

  const targets = [
    { label: 'WORKSTATION CENTER', pos: { x: 380, y: 180, z: 0 }, pitch: 0 },
    { label: 'INBOUND TRAY', pos: { x: 340, y: 90, z: -160 }, pitch: -45 },
    { label: 'OUTBOUND FIXTURE', pos: { x: 280, y: 95, z: 180 }, pitch: -45 },
    { label: 'HIGH OVERHEAD CLEARANCE', pos: { x: 200, y: 480, z: 0 }, pitch: 30 },
  ];

  const handleApply = (newX = posX, newY = posY, newZ = posZ, newP = pitch) => {
    onUpdateTargetPos({ x: newX, y: newY, z: newZ }, newP);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
      {/* Target Workstation Presets */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
        <span className="tactical-title" style={{ fontSize: '11px', color: 'var(--text-muted)' }}>
          CARTESIAN TARGET PRESETS:
        </span>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '6px' }}>
          {targets.map((t) => (
            <button
              key={t.label}
              disabled={!isEngaged}
              onClick={() => {
                setPosX(t.pos.x);
                setPosY(t.pos.y);
                setPosZ(t.pos.z);
                setPitch(t.pitch);
                handleApply(t.pos.x, t.pos.y, t.pos.z, t.pitch);
              }}
              className="tactical-btn"
              style={{ minHeight: '30px', padding: '0 8px', fontSize: '10px', textAlign: 'left', justifyContent: 'flex-start' }}
            >
              <Navigation size={12} /> {t.label}
            </button>
          ))}
        </div>
      </div>

      {/* Numerical Coordinate Sliders */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        {/* X Axis */}
        <div style={{ background: 'rgba(0,0,0,0.25)', padding: '8px 10px', borderRadius: '6px', border: '1px solid rgba(255,255,255,0.05)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '4px', fontSize: '11px' }}>
            <span style={{ color: 'var(--accent-cyan)', fontWeight: 700 }}>X AXIS (FORWARD/AFT)</span>
            <span>TARGET: <b>{posX.toFixed(0)} mm</b> | ACT: <b>{currentTcp.x.toFixed(0)} mm</b></span>
          </div>
          <input
            type="range"
            min={-550}
            max={550}
            step={5}
            value={posX}
            disabled={!isEngaged}
            onChange={(e) => {
              const val = parseFloat(e.target.value);
              setPosX(val);
              handleApply(val, posY, posZ, pitch);
            }}
            style={{ width: '100%' }}
          />
        </div>

        {/* Y Axis */}
        <div style={{ background: 'rgba(0,0,0,0.25)', padding: '8px 10px', borderRadius: '6px', border: '1px solid rgba(255,255,255,0.05)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '4px', fontSize: '11px' }}>
            <span style={{ color: 'var(--accent-emerald)', fontWeight: 700 }}>Y AXIS (ELEVATION/HEIGHT)</span>
            <span>TARGET: <b>{posY.toFixed(0)} mm</b> | ACT: <b>{currentTcp.y.toFixed(0)} mm</b></span>
          </div>
          <input
            type="range"
            min={20}
            max={650}
            step={5}
            value={posY}
            disabled={!isEngaged}
            onChange={(e) => {
              const val = parseFloat(e.target.value);
              setPosY(val);
              handleApply(posX, val, posZ, pitch);
            }}
            style={{ width: '100%' }}
          />
        </div>

        {/* Z Axis */}
        <div style={{ background: 'rgba(0,0,0,0.25)', padding: '8px 10px', borderRadius: '6px', border: '1px solid rgba(255,255,255,0.05)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '4px', fontSize: '11px' }}>
            <span style={{ color: 'var(--accent-blue)', fontWeight: 700 }}>Z AXIS (LATERAL REACH)</span>
            <span>TARGET: <b>{posZ.toFixed(0)} mm</b> | ACT: <b>{currentTcp.z.toFixed(0)} mm</b></span>
          </div>
          <input
            type="range"
            min={-550}
            max={550}
            step={5}
            value={posZ}
            disabled={!isEngaged}
            onChange={(e) => {
              const val = parseFloat(e.target.value);
              setPosZ(val);
              handleApply(posX, posY, val, pitch);
            }}
            style={{ width: '100%' }}
          />
        </div>

        {/* Pitch Angle */}
        <div style={{ background: 'rgba(0,0,0,0.25)', padding: '8px 10px', borderRadius: '6px', border: '1px solid rgba(255,255,255,0.05)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '4px', fontSize: '11px' }}>
            <span style={{ color: 'var(--accent-amber)', fontWeight: 700 }}>WRIST PITCH ANGLE</span>
            <span>TARGET: <b>{pitch.toFixed(0)}°</b></span>
          </div>
          <input
            type="range"
            min={-90}
            max={90}
            step={2}
            value={pitch}
            disabled={!isEngaged}
            onChange={(e) => {
              const val = parseFloat(e.target.value);
              setPitch(val);
              handleApply(posX, posY, posZ, val);
            }}
            style={{ width: '100%' }}
          />
        </div>
      </div>

      {/* IK Solver Status Diagnostics */}
      <div
        style={{
          background: 'rgba(0, 0, 0, 0.35)',
          padding: '10px 12px',
          borderRadius: '6px',
          border: '1px solid var(--border-subtle)',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          fontSize: '11px',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          {ikConverged ? (
            <CheckCircle2 size={16} color="var(--accent-emerald)" />
          ) : (
            <AlertTriangle size={16} color="var(--accent-rose)" />
          )}
          <span>
            IK STATUS:{' '}
            <b style={{ color: ikConverged ? 'var(--accent-emerald)' : 'var(--accent-rose)' }}>
              {ikConverged ? 'CONVERGED (STABLE)' : 'OUT OF REACH / SINGULAR'}
            </b>
          </span>
        </div>
        <div style={{ display: 'flex', gap: '12px' }}>
          <span>RESIDUAL: <b>{ikErrorMm.toFixed(2)} mm</b></span>
          <span>DEXTERITY: <b>{(manipulability * 100).toFixed(0)}%</b></span>
        </div>
      </div>

      <button
        disabled={!isEngaged}
        onClick={onSolveIK}
        className="tactical-btn tactical-btn-primary"
        style={{ height: '36px', width: '100%' }}
      >
        <Crosshair size={14} /> RE-SOLVE INVERSE KINEMATICS MATRIX
      </button>
    </div>
  );
};

