input.content:
import React, { useState } from 'react';
import { FATScenarioId, ScenarioResult } from '../../types/testSuite';
import { Activity, CheckCircle2, Play, AlertCircle, ShieldAlert } from 'lucide-react';

interface FATSuitePanelProps {
  results: Record<FATScenarioId, ScenarioResult>;
  activeScenario: FATScenarioId | null;
  onRunScenario: (id: FATScenarioId) => void;
  isEngaged: boolean;
}

export const FATSuitePanel: React.FC<FATSuitePanelProps> = ({
  results,
  activeScenario,
  onRunScenario,
  isEngaged,
}) => {
  const [selectedId, setSelectedId] = useState<FATScenarioId>('REPEATABILITY');

  const scenarios: { id: FATScenarioId; title: string; standard: string; desc: string }[] = [
    {
      id: 'REPEATABILITY',
      title: 'ISO-9283 Repeatability Protocol',
      standard: 'ISO 9283 §7.2',
      desc: 'Multi-cycle target pose return deviation benchmark (Tolerance: ±0.05 mm).',
    },
    {
      id: 'PAYLOAD_STRESS',
      title: 'Cantilever Payload Stress',
      standard: 'ISO 10218-1 §5.4',
      desc: 'Full horizontal cantilever static load and torque deflection test at 5.0 kg.',
    },
    {
      id: 'SINGULARITY',
      title: 'Singularity DLS Boundary Test',
      standard: 'IEEE Trans. Robotics',
      desc: 'Collinear elbow boundary transit verifying Damped Least Squares stability.',
    },
    {
      id: 'ESTOP_BRAKING',
      title: 'Dynamic Braking Deceleration',
      standard: 'EN ISO 13849-1 Cat 4',
      desc: 'Full-slew emergency stop deceleration and stopping distance verification.',
    },
  ];

  const currentResult = results[selectedId];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
      {/* Scenario Selection Grid */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
        <span className="tactical-title" style={{ fontSize: '11px', color: 'var(--text-muted)' }}>
          FACTORY ACCEPTANCE TEST (FAT) PROTOCOLS:
        </span>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
          {scenarios.map((sc) => {
            const res = results[sc.id];
            const isSelected = selectedId === sc.id;
            const isRunning = activeScenario === sc.id;

            return (
              <div
                key={sc.id}
                onClick={() => setSelectedId(sc.id)}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  padding: '8px 10px',
                  borderRadius: '6px',
                  background: isSelected ? 'rgba(0, 242, 254, 0.12)' : 'rgba(0,0,0,0.2)',
                  border: isSelected ? '1px solid var(--accent-cyan)' : '1px solid rgba(255,255,255,0.05)',
                  cursor: 'pointer',
                }}
              >
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <span style={{ fontSize: '12px', fontWeight: 600, color: '#fff' }}>
                      {sc.title}
                    </span>
                    <span style={{ fontSize: '9px', padding: '1px 5px', borderRadius: '3px', background: 'rgba(255,255,255,0.1)', color: 'var(--text-muted)' }}>
                      {sc.standard}
                    </span>
                  </div>
                  <div style={{ fontSize: '10px', color: 'var(--text-muted)', marginTop: '2px' }}>
                    {sc.desc}
                  </div>
                </div>

                <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <span
                    style={{
                      fontSize: '10px',
                      fontWeight: 700,
                      padding: '2px 6px',
                      borderRadius: '4px',
                      background:
                        res.status === 'PASSED'
                          ? 'rgba(0,245,160,0.2)'
                          : res.status === 'RUNNING'
                          ? 'rgba(0,242,254,0.2)'
                          : 'rgba(255,255,255,0.05)',
                      color:
                        res.status === 'PASSED'
                          ? 'var(--accent-emerald)'
