import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Header } from './components/Header';
import { TelemetryStrip } from './components/TelemetryStrip';
import { Viewport3D } from './components/Viewport3D';
import { JogControlPanel } from './components/panels/JogControlPanel';
import { CartesianControlPanel } from './components/panels/CartesianControlPanel';
import { TrajectoryControlPanel } from './components/panels/TrajectoryControlPanel';
import { FATSuitePanel } from './components/panels/FATSuitePanel';
import { BlackboxPanel } from './components/panels/BlackboxPanel';

import { KinematicsEngine, JointPositions3D } from './engine/kinematicsEngine';
import { DynamicsEngine } from './engine/dynamicsEngine';
import { GripperEngine } from './engine/gripperEngine';
import { TrajectoryEngine } from './engine/trajectoryEngine';
import { TestScenarioRunner } from './engine/testScenarioRunner';
import { roboticSound } from './services/soundEngine';
import { blackboxRecorder } from './services/blackboxRecorder';
import { PRESET_PROGRAMS } from './services/presetPrograms';

import { Pose3D, Vector3D, Workpiece } from './types/arm';
import { ControlMode, ServoState, TelemetryFrame } from './types/telemetry';
import { TrajectoryProgram, Waypoint } from './types/trajectory';
import { FATScenarioId } from './types/testSuite';

const INITIAL_ANGLES = [0, 30, 45, -75, 0, 30];

export const App: React.FC = () => {
  // Engines
  const kinematics = useMemo(() => new KinematicsEngine(), []);
  const dynamics = useMemo(() => new DynamicsEngine(), []);
  const gripper = useMemo(() => new GripperEngine(), []);
  const trajectory = useMemo(() => new TrajectoryEngine(), []);
  const testRunner = useMemo(() => new TestScenarioRunner(), []);

  // System States
  const [servoState, setServoState] = useState<ServoState>('ENGAGED');
  const [controlMode, setControlMode] = useState<ControlMode>('JOG');
  const [isAudioMuted, setIsAudioMuted] = useState(true);
  const [cycleCount, setCycleCount] = useState(1);

  // Targets
  const [targetAngles, setTargetAngles] = useState<number[]>([...INITIAL_ANGLES]);
  const [gripperWidth, setGripperWidth] = useState(60.0);
  const [targetPos, setTargetPos] = useState<Vector3D>({ x: 380, y: 180, z: 0 });
  const [targetPitch, setTargetPitch] = useState(0);

  // Trajectory & Tests
  const [activeProgram, setActiveProgram] = useState<TrajectoryProgram>(PRESET_PROGRAMS[0]);
  const [activeWaypoint, setActiveWaypoint] = useState<Waypoint | null>(null);
  const [trajProgress, setTrajProgress] = useState(0);
  const [activeScenario, setActiveScenario] = useState<FATScenarioId | null>(null);

  // IK Feedback
  const [ikConverged, setIkConverged] = useState(true);
  const [ikErrorMm, setIkErrorMm] = useState(0.0);

  // Simulation output states for rendering
  const [positions, setPositions] = useState<JointPositions3D>(() => kinematics.forwardKinematics(INITIAL_ANGLES).positions);
  const [tcpPose, setTcpPose] = useState<Pose3D>(() => kinematics.forwardKinematics(INITIAL_ANGLES).tcpPose);
  const [workpieces, setWorkpieces] = useState<Workpiece[]>([]);
  const [telemetry, setTelemetry] = useState<TelemetryFrame>(() => {
    const dyn = dynamics.update(0.016, INITIAL_ANGLES, 0, false);
    const fk = kinematics.forwardKinematics(INITIAL_ANGLES);
    return {
      timestamp: 0,
      servoState: 'ENGAGED',
      controlMode: 'JOG',
      joints: dyn.joints,
      tcpPose: fk.tcpPose,
      targetPose: fk.tcpPose,
      endEffector: {
        pose: fk.tcpPose,
        targetPose: fk.tcpPose,
        gripperWidthMm: 60,
        isGripping: false,
        gripForceN: 0,
        grippedObjectId: null,
        wrench: dyn.wrench,
        tableDistanceMm: fk.tcpPose.position.y,
      },
      power: dyn.power,
      manipulability: kinematics.computeManipulability(INITIAL_ANGLES),
      cycleCount: 1,
      warnings: [],
    };
  });

  // Setup Trajectory callback
  useEffect(() => {
    trajectory.setProgram(activeProgram);
    trajectory.setCallback((wp) => {
      setActiveWaypoint(wp);
      roboticSound.playWaypointChime();
      if (wp.gripperAction !== 'NONE') {
        roboticSound.playGripperSolenoid();
      }
    });
  }, [trajectory, activeProgram]);

  // Main High-Frequency Simulation Loop
  const simRef = useRef({
    servoState,
    controlMode,
    targetAngles,
    gripperWidth,
    targetPos,
    targetPitch,
  });
  simRef.current = { servoState, controlMode, targetAngles, gripperWidth, targetPos, targetPitch };

  useEffect(() => {
    let lastTime = performance.now();
    let animId = 0;
    let payloadKg = 0;

    const tick = (now: number) => {
      animId = requestAnimationFrame(tick);
      const dt = Math.min(0.05, Math.max(0.001, (now - lastTime) / 1000));
      lastTime = now;

      const { servoState: curServo, controlMode: curMode } = simRef.current;
      const isEstop = curServo === 'ESTOP';
      const isEngaged = curServo === 'ENGAGED';
      const actualAngles = dynamics.getActualAngles();

      let commandedJoints = [...simRef.current.targetAngles];
      let commandedGripper = simRef.current.gripperWidth;

      // Mode-specific controller inputs
      if (curMode === 'TRAJECTORY' && isEngaged) {
        const traj = trajectory.update(dt, actualAngles);
        commandedJoints = traj.commandedJoints;
        commandedGripper = traj.commandedGripperWidth;
        setActiveWaypoint(traj.activeWaypoint);
        setTrajProgress(traj.progressPct);
      } else if (curMode === 'FAT_CYCLE' && isEngaged) {
        const test = testRunner.update(dt, kinematics, dynamics);
        if (test.targetAngles) commandedJoints = test.targetAngles;
        setActiveScenario(test.activeScenario);
      }

      // Physics & Dynamics update
      const dyn = dynamics.update(dt, isEngaged ? commandedJoints : actualAngles, payloadKg, isEstop);
      const fk = kinematics.forwardKinematics(actualAngles);
      const grip = gripper.update(dt, commandedGripper, fk.tcpPose.position);
      payloadKg = grip.totalPayloadKg;

      const manipulability = kinematics.computeManipulability(actualAngles);

      // Acoustic motor simulation
      const totalVel = dyn.joints.reduce((acc, j) => acc + Math.abs(j.velocityDegPerSec), 0);
      roboticSound.updateMotorSound(totalVel);

      // Telemetry frame
      const frame: TelemetryFrame = {
        timestamp: Number((now / 1000).toFixed(2)),
        servoState: curServo,
        controlMode: curMode,
        joints: dyn.joints,
        tcpPose: fk.tcpPose,
        targetPose: { position: simRef.current.targetPos, orientation: fk.tcpPose.orientation },
        endEffector: {
          pose: fk.tcpPose,
          targetPose: fk.tcpPose,
          gripperWidthMm: grip.currentWidthMm,
          isGripping: grip.isGripping,
          gripForceN: grip.gripForceN,
          grippedObjectId: grip.grippedObjectId,
          wrench: dyn.wrench,
          tableDistanceMm: fk.tcpPose.position.y,
        },
        power: dyn.power,
        manipulability,
        cycleCount,
        warnings: [],
      };

      blackboxRecorder.addFrame(frame);
      setPositions(fk.positions);
      setTcpPose(fk.tcpPose);
      setWorkpieces([...grip.workpieces]);
      setTelemetry(frame);
    };

    animId = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(animId);
  }, [kinematics, dynamics, gripper, trajectory, testRunner, cycleCount]);

  // Master Actions
  const handleToggleServo = () => {
    if (servoState === 'ESTOP') return;
    setServoState((prev) => (prev === 'ENGAGED' ? 'DISENGAGED' : 'ENGAGED'));
  };

  const handleToggleEStop = () => {
    if (servoState === 'ESTOP') {
      setServoState('DISENGAGED');
    } else {
      setServoState('ESTOP');
      trajectory.pause();
    }
  };

  const handleResetHome = () => {
    dynamics.resetToHome();
    gripper.reset();
    trajectory.stop();
    setTargetAngles([...INITIAL_ANGLES]);
    setGripperWidth(60);
    setCycleCount((c) => c + 1);
    setControlMode('JOG');
  };

  const handleToggleAudio = () => {
    const nextMute = !isAudioMuted;
    setIsAudioMuted(nextMute);
    roboticSound.setMute(nextMute);
  };

  const handleSolveIK = () => {
    const actual = dynamics.getActualAngles();
    const res = kinematics.inverseKinematics(targetPos, actual, targetPitch);
    setIkConverged(res.converged);
    setIkErrorMm(res.errorMm);
    if (res.converged) {
      setTargetAngles([...res.anglesDeg]);
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh', width: '100vw', background: 'var(--bg-primary)' }}>
      {/* 1. Header Navigation & State Controls */}
      <Header
        telemetry={telemetry}
        servoState={servoState}
        controlMode={controlMode}
        isAudioMuted={isAudioMuted}
        onToggleServoPower={handleToggleServo}
        onToggleEStop={handleToggleEStop}
        onSelectControlMode={(mode) => {
          setControlMode(mode);
          if (mode === 'HOME') handleResetHome();
        }}
        onToggleAudio={handleToggleAudio}
        onResetToHome={handleResetHome}
      />

      {/* 2. Top Telemetry Strip */}
      <TelemetryStrip telemetry={telemetry} />

      {/* 3. Main Workspace Layout */}
      <div style={{ display: 'flex', flex: 1, margin: '0 8px 8px 8px', gap: '8px', overflow: 'hidden' }}>
        {/* Left: 3D Three.js Viewport */}
        <div className="tactical-panel" style={{ flex: 1, position: 'relative', overflow: 'hidden', minWidth: '400px' }}>
          <Viewport3D
            positions={positions}
            gripperWidthMm={telemetry.endEffector.gripperWidthMm}
            workpieces={workpieces}
            tcpPose={tcpPose}
          />
        </div>

        {/* Right: Tactical Control Station */}
        <div
          className="tactical-panel"
          style={{
            width: '440px',
            padding: '14px',
            display: 'flex',
            flexDirection: 'column',
            overflowY: 'auto',
          }}
        >
          {controlMode === 'JOG' && (
            <JogControlPanel
              jointStates={telemetry.joints}
              targetAngles={targetAngles}
              gripperWidth={gripperWidth}
              onUpdateTargetAngle={(idx, deg) => {
                const next = [...targetAngles];
                next[idx] = deg;
                setTargetAngles(next);
              }}
              onUpdateGripperWidth={(w) => setGripperWidth(w)}
              onApplyPresetPose={(angles) => setTargetAngles([...angles])}
              isEngaged={servoState === 'ENGAGED'}
            />
          )}

          {controlMode === 'CARTESIAN' && (
            <CartesianControlPanel
              currentTcp={tcpPose.position}
              targetPos={targetPos}
              targetPitch={targetPitch}
              manipulability={telemetry.manipulability}
              ikErrorMm={ikErrorMm}
              ikConverged={ikConverged}
              onUpdateTargetPos={(pos, pitch) => {
                setTargetPos(pos);
                setTargetPitch(pitch);
                const actual = dynamics.getActualAngles();
                const res = kinematics.inverseKinematics(pos, actual, pitch);
                setIkConverged(res.converged);
                setIkErrorMm(res.errorMm);
                if (res.converged) setTargetAngles([...res.anglesDeg]);
              }}
              onSolveIK={handleSolveIK}
              isEngaged={servoState === 'ENGAGED'}
            />
          )}

          {controlMode === 'TRAJECTORY' && (
            <TrajectoryControlPanel
              activeProgram={activeProgram}
              onSelectProgram={(p) => setActiveProgram(p)}
              isRunning={trajectory.getStatus().isRunning}
              activeWaypoint={activeWaypoint}
              progressPct={trajProgress}
              onPlay={() => trajectory.start()}
              onPause={() => trajectory.pause()}
              onStop={() => trajectory.stop()}
              onToggleLoop={() => {
                activeProgram.loop = !activeProgram.loop;
                setActiveProgram({ ...activeProgram });
              }}
              isEngaged={servoState === 'ENGAGED'}
            />
          )}

          {controlMode === 'FAT_CYCLE' && (
            <FATSuitePanel
              results={testRunner.getResults()}
              activeScenario={activeScenario}
              onRunScenario={(id) => testRunner.startScenario(id)}
              isEngaged={servoState === 'ENGAGED'}
            />
          )}

          {controlMode === 'HOME' && (
            <BlackboxPanel
              power={telemetry.power}
              joints={telemetry.joints}
              cycleCount={telemetry.cycleCount}
            />
          )}
        </div>
      </div>
    </div>
  );
};

